ItemEvents.crafted((e) => {
  const key = SF_EVIDENCE[String(e.item.id)];
  if (!key) return;
  const p = e.player || e.entity;
  try { ProgressiveStages.addCounter(p, key, 1); } catch (err) {
    console.log('[starforge] counter bump failed: ' + err);
  }
});

