// ---- entity-spawn detections (nearest player owns the event) ----
const SF_SPAWNS = {"guardvillagers:guard":[{"counter":"modpack:guard_post","advancement":"armed_garrison","once":true,"flag":"sf_ev_guard_posted"}]};
for (const entId of Object.keys(SF_SPAWNS)) {
  EntityEvents.spawned(entId, (e) => {
    try {
      const p = e.level.getNearestPlayer(e.entity, 64);
      if (p) sfEmit(p, SF_SPAWNS[entId]);
    } catch (err) {}
  });
}

// ---- TaCZ gun-namespace detection via GunId NBT ----
const SF_GUN_EV = [{"counter":"modpack:eos_gun","advancement":"eos_arsenal","hint":"modpack.message.eos_gun_tip","once":true,"flag":"sf_ev_eos_gun"}];
PlayerEvents.inventoryChanged('tacz:modern_kinetic_gun', (e) => {
  try {
    const nbt = e.item.nbt;
    if (!nbt || !nbt.GunId) return;
    if (!String(nbt.GunId).startsWith("eos:")) return;
    sfEmit(e.player, SF_GUN_EV);
  } catch (err) {}
});

// ---- alien-dimension artifact scan (throttled; nothing per-tick) ----
const SF_ALIEN_SET = new Set(["artifacts:anglers_hat","artifacts:antidote_vessel","artifacts:aqua_dashers","artifacts:bunny_hoppers","artifacts:charm_of_shrinking","artifacts:charm_of_sinking","artifacts:chorus_totem","artifacts:cloud_in_a_bottle","artifacts:cowboy_hat","artifacts:cross_necklace","artifacts:crystal_heart","artifacts:digging_claws","artifacts:eternal_steak","artifacts:everlasting_beef","artifacts:feral_claws","artifacts:fire_gauntlet","artifacts:flame_pendant","artifacts:flippers","artifacts:golden_hook","artifacts:helium_flamingo","artifacts:kitty_slippers","artifacts:lucky_scarf","artifacts:night_vision_goggles","artifacts:novelty_drinking_hat","artifacts:obsidian_skull","artifacts:onion_ring","artifacts:panic_necklace","artifacts:pickaxe_heater","artifacts:plastic_drinking_hat","artifacts:pocket_piston","artifacts:power_glove","artifacts:rooted_boots","artifacts:running_shoes","artifacts:scarf_of_invisibility","artifacts:shock_pendant","artifacts:snorkel","artifacts:snowshoes","artifacts:steadfast_spikes","artifacts:strider_shoes","artifacts:superstitious_hat","artifacts:thorn_pendant","artifacts:umbrella","artifacts:universal_attractor","artifacts:vampiric_glove","artifacts:villager_hat","artifacts:warp_drive","artifacts:whoopee_cushion","artifacts:withered_bracelet"]);
const SF_ALIEN_EV = [{"advancement":"alien_artifact","hint":"modpack.hint.alien_artifact","once":true,"flag":"sf_ev_alien_artifact"}];
const SF_ALIEN_DIMS = new Set(["ad_astra:moon","ad_astra:mars","ad_astra:venus","ad_astra:mercury","ad_astra:glacio","pv_asteroid_belt:asteroid_belt"]);
// event-driven primary path: picking an artifact up inside an alien dimension
for (const itemId of SF_ALIEN_SET) {
  PlayerEvents.inventoryChanged(itemId, (e) => {
    try {
      if (SF_ALIEN_DIMS.has(String(e.player.level.dimension().location()))) sfEmit(e.player, SF_ALIEN_EV);
    } catch (err) {}
  });
}
// throttled fallback: covers carrying an artifact into the dimension and any
// inventory mutations inventoryChanged cannot see (curio equips etc.)
PlayerEvents.tick((e) => {
  const p = e.player;
  if (!p || (p.server.getTickCount() + p.getId()) % 40 !== 0) return;
  if (SF_ALIEN_EV.every((ev) => p.persistentData.getBoolean(ev.flag))) return;
  try {
    if (!SF_ALIEN_DIMS.has(String(p.level.dimension().location()))) return;
    for (const stack of p.inventory.allItems) {
      if (SF_ALIEN_SET.has(String(stack.id))) { sfEmit(p, SF_ALIEN_EV); break; }
    }
  } catch (err) {}
});

PlayerEvents.advancement('starforge:moon_landing', (e) => sfEmit(e.player, [{"hint":"modpack.hint.first_moon","once":true,"flag":"sf_ev_first_moon"}]));

PlayerEvents.advancement('starforge:belt_arrival', (e) => sfEmit(e.player, [{"hint":"modpack.hint.first_belt","once":true,"flag":"sf_ev_first_belt"}]));

// ---- horde events (NativeEvents; data layer only - presentation stays in starforge_horde.js) ----
const SF_HORDE_START = [{"advancement":"first_horde","hint":"modpack.hint.first_horde","once":true,"flag":"sf_ev_first_horde"}];
const SF_HORDE_END = [{"counter":"modpack:horde_survived","advancement":"horde_survived","flag":"sf_ev_horde_survived"}];
NativeEvents.onEvent(SF_HordeStartEvent, (e) => { const p = e.getPlayer(); if (p) sfEmit(p, SF_HORDE_START); });
NativeEvents.onEvent(SF_HordeEndEvent, (e) => { const p = e.getPlayer(); if (p) sfEmit(p, SF_HORDE_END); });

// ---- quest-completion counters (optional FTB path; absent file -> no-op) ----
const SF_QUEST_EV = {"6FD4163A437DB329":[{"counter":"modpack:base_registered","advancement":"base_registered","once":true,"flag":"sf_ev_base_registered"}],"17108BC68E5E17B5":[{"advancement":"alien_ruins","hint":"modpack.hint.alien_ruins","once":true,"flag":"sf_ev_alien_ruins"}]};
function sfPollQuests(p) {
  try {
    const f = SF_SQF.getInstance ? SF_SQF.getInstance() : SF_SQF.INSTANCE;
    const file = f && f.orElse ? f.orElse(null) : f;
    if (!file || !file.getTeamData) return;
    const td = file.getTeamData(p);
    if (!td || !td.isPresent || !td.isPresent()) return;
    const data = td.get();
    for (const hex of Object.keys(SF_QUEST_EV)) {
      const q = file.getQuest(SF_Long.parseLong(hex, 16));
      if (q && data.isCompleted(q)) sfEmit(p, SF_QUEST_EV[hex]);
    }
  } catch (err) {}
}
PlayerEvents.loggedIn((e) => sfPollQuests(e.player));
// 200-tick fallback poll, staggered per player: FTB Quests' completion event
// lives on its own architectury bus, not the NeoForge event bus, so KubeJS
// cannot subscribe to it directly - polling stays, just never in lockstep.
PlayerEvents.tick((e) => {
  const p = e.player;
  if (!p || (p.server.getTickCount() + p.getId()) % 200 !== 0) return;
  sfPollQuests(p);
});

// ---- stage hooks: advancement sync + next-step hint ----
const SF_STAGE_ADV = {"modpack:mechanical_age":"mechanical_age","modpack:electric_age":"electric_age","modpack:information_age":"information_age","modpack:heavy_industry_age":"heavy_industry_age","modpack:atomic_age":"atomic_age","modpack:space_age":"space_age","modpack:quantum_age":"quantum_age"};
const SF_STAGE_NEXT = {"modpack:survival_age":"modpack.stage.survival_age.next","modpack:mechanical_age":"modpack.stage.mechanical_age.next","modpack:electric_age":"modpack.stage.electric_age.next","modpack:information_age":"modpack.stage.information_age.next","modpack:heavy_industry_age":"modpack.stage.heavy_industry_age.next","modpack:atomic_age":"modpack.stage.atomic_age.next","modpack:space_age":"modpack.stage.space_age.next","modpack:quantum_age":"modpack.stage.quantum_age.next"};
ProgressiveStages.onGranted((p, stage) => {
  try {
    const adv = SF_STAGE_ADV[String(stage)];
    if (adv) sfAward(p, adv);
    const key = SF_STAGE_NEXT[String(stage)];
    if (key && sfOnce(p, 'sf_next_' + stage)) p.tell(Text.translate(key));
  } catch (err) {}
});
